      [0, 0, 0, 10, 20, 75],
      [0, 0, 0, 10, 20, 75],
      [0, 0, 0, 0, 0, 0],
    ];
  }

  fromScatterCountToFreeSpinNumber(scatterCount: number): number {
    switch (scatterCount) {
      case 3: {
        return 10;
      }
      case 4: {
        return 12;
      }
      case 5: {
        return 15;
      }
      default: {
        return 0;
      }
    }
  }

  fromFreeSpinNumberToScatterCount(freeSpinNumber: number): number {
    switch (freeSpinNumber) {
      case 10: {
        return 3;
      }
      case 12: {
        return 4;
      }
      case 15: {
        return 5;
      }
      default: {
        return 0;
      }
    }
  }

  getInitialShotsByScatterCount(scatterCount: number): number {
    switch (scatterCount) {
      case 5: {
        return 7;
      }
      case 4: {
        return 5;
      }
      case 3: {
        return 3;
      }
      default: {
        return 0;
      }
    }
  }
}


